import java.util.*;

class Node {

    public int val;
    public List<Node> neighbors;

    public Node() {
        val = 0;
        neighbors = new ArrayList<>();
    }

    public Node(int val) {
        this.val = val;
        neighbors = new ArrayList<>();
    }
}

class Solution {

    private Map<Node, Node> map = new HashMap<>();

    public Node cloneGraph(Node node) {

        if (node == null) {
            return null;
        }

        if (map.containsKey(node)) {
            return map.get(node);
        }

        Node clone = new Node(node.val);

        map.put(node, clone);

        for (Node neighbor : node.neighbors) {
            clone.neighbors.add(cloneGraph(neighbor));
        }

        return clone;
    }

    // Build graph from adjacency list
    private static Node buildGraph(int[][] adjList) {

        if (adjList.length == 0) {
            return null;
        }

        Node[] nodes = new Node[adjList.length];

        for (int i = 0; i < adjList.length; i++) {
            nodes[i] = new Node(i + 1);
        }

        for (int i = 0; i < adjList.length; i++) {

            for (int neighbor : adjList[i]) {
                nodes[i].neighbors.add(nodes[neighbor - 1]);
            }
        }

        return nodes[0];
    }

    // Convert graph back to adjacency list
    private static List<List<Integer>> toAdjList(Node node) {

        List<List<Integer>> result = new ArrayList<>();

        if (node == null) {
            return result;
        }

        Map<Node, Integer> visited = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();

        queue.offer(node);
        visited.put(node, 1);

        while (!queue.isEmpty()) {

            Node current = queue.poll();

            while (result.size() < current.val) {
                result.add(new ArrayList<>());
            }

            for (Node neighbor : current.neighbors) {

                result.get(current.val - 1).add(neighbor.val);

                if (!visited.containsKey(neighbor)) {
                    visited.put(neighbor, neighbor.val);
                    queue.offer(neighbor);
                }
            }
        }

        return result;
    }

    public static void main(String[] args) {

        // Custom DevScribe input
        int[][] adjList = Input.get2DIntArray("adjList");

        Node graph = buildGraph(adjList);

        Solution sol = new Solution();

        Node clone = sol.cloneGraph(graph);

        System.out.println(toAdjList(clone));
    }
}
